import subprocess
import sys

# Try to find fast_parquet in any Python path
for path in sys.path:
    pkg_path = f"{path}/fast_parquet"
    try:
        from importlib.util import find_spec
        spec = find_spec('fast_parquet')
        if spec:
            print(f"Found fast_parquet at: {spec.origin}")
            break
    except (ImportError, ModuleNotFoundError):
        continue
else:
    print("fast_parquet not found in any Python path")

# Try to run the gh CLI directly
print("\n=== Running gh search repos for limine profile patterns ===")
try:
    result = subprocess.run(['gh', 'search', 'repos', 'limine', 'profile', 'boot', '--limit', '50'], capture_output=True, text=True, check=False)
    if result.returncode == 0:
        lines = result.stdout.strip().split('\n')
        for line in lines[:30]:
            if line.strip():
                print(line)
    else:
        print(f"gh command failed with: {result.stderr[:500]}")
except FileNotFoundError:
    print("gh CLI not found")

