#!/usr/bin/env bun

/**
 * gh-limine.ts - GitHub CLI control scripts for limine kernel profile management
 * Uses Bun for fast GitHub search, API calls, and profile management
 */

import { $ } from 'bun'
import fs from 'fs'
import path from 'path'

// ============================================================================
// Modular venv-like setup for Bun dependencies
// ============================================================================

const VENV_PATH = path.join(process.env.HOME || '~', '.venv', 'gh-limine')
const VENV_ACTIVATE = path.join(VENV_PATH, 'activate')

// Bun dependencies for fast GitHub search and profile management
const BUN_DEPS = [
  'fast-github',  // Fast GitHub API client
  'pyarrow',      // Arrow bindings for data processing
  'fastparquet',  // Fast parquet reading/writing
  'requests',     // HTTP client (Node.js compatible)
  'aiohttp',      // Async HTTP for parallel searches
  'tqdm',         // Progress bars
  'chalk',        // Colored terminal output
  'inquirer'      // Interactive prompts
]

/**
 * Ensure Bun venv is set up with dependencies
 */
async function ensureBunVenv() {
  const venvExists = fs.existsSync(VENV_ACTIVATE)

  if (!venvExists) {
    console.log('[gh-limine] Setting up Bun venv at', VENV_PATH)

    // Create venv directory
    await $`mkdir -p ${VENV_PATH}`

    // Install Bun
    if (!fs.existsSync(path.join(VENV_PATH, 'bun'))) {
      await $`curl -fsSL https://bun.sh/install | bash -s -- --prefix ${VENV_PATH}`
    }

    // Initialize Bun project and install dependencies
    await $`cd ${VENV_PATH} && bun init --default`
    await $`cd ${VENV_PATH} && bun add ${BUN_DEPS.join(' ')}`

    console.log('[gh-limine] Bun venv ready at', VENV_PATH)
  }

  // Always use Bun from venv
  const bunPath = path.join(VENV_PATH, 'bun')
  return bunPath
}

// ============================================================================
// GitHub search functions
// ============================================================================

const LIMINE_REPOS = {
  bootloader: 'Limine-Bootloader/Limine',
  protocol: 'Limine-Bootloader/limine-protocol',
  ctemplate: 'Limine-Bootloader/limine-c-template',
  rusttemplate: 'Limine-Bootloader/limine-rust-template',
  zigtemplate: 'Limine-Bootloader/limine-zig-template'
}

/**
 * Search for limine repos using Bun's fast GitHub API client
 */
async function searchLimine(query: string = 'limine', limit: number = 50) {
  const bunPath = await ensureBunVenv()

  // Use Bun's built-in fetch (fast, no external deps)
  const apiURL = 'https://api.github.com/search/repositories'
  const searchQuery = `limine ${query}`

  const headers: Record<string, string> = {
    'Accept': 'application/vnd.github.v3+json'
  }

  const token = process.env.GITHUB_TOKEN || ''
  if (token) {
    headers['Authorization'] = `token ${token}`
  }

  const params = new URLSearchParams({
    q: searchQuery,
    sort: 'updated',
    order: 'desc',
    per_page: Math.min(100, limit * 2)
  })

  try {
    const response = await fetch(`${apiURL}?${params}`, {
      headers,
      timeout: 10000
    })

    if (response.ok) {
      const data = await response.json()
      const repos = data.items || []

      console.log(`[gh-limine] Found ${repos.length} repos for "${searchQuery}"`)

      // Format output
      for (const repo of repos.slice(0, limit)) {
        const name = repo.full_name || ''
        const description = repo.description || ''
        const private = repo.private ? 'private' : 'public'
        const updated = repo.updated_at || ''

        console.log(`${name}\t${description.substring(0, 100)}...\t${private}\t${updated}`)
      }

      return repos
    } else {
      console.error(`[gh-limine] GitHub API error: ${response.status}`)
      return []
    }
  } catch (error) {
    console.error(`[gh-limine] Search failed:`, error)
    return []
  }
}

/**
 * View a limine repo's README
 */
async function viewLimineReadme(repo: string = LIMINE_REPOS.bootloader, path: string = 'README.md') {
  const bunPath = await ensureBunVenv()

  const apiURL = `https://api.github.com/repos/${repo}/contents/${path}`
  const headers: Record<string, string> = {
    'Accept': 'application/vnd.github.v3+raw'  // Raw content, not HTML
  }

  const token = process.env.GITHUB_TOKEN || ''
  if (token) {
    headers['Authorization'] = `token ${token}`
  }

  try {
    const response = await fetch(apiURL, { headers })

    if (response.ok) {
      const data = await response.json()
      const content = data.content || ''

      // Decode base64 content
      const decoded = Buffer.from(content, 'base64').toString('utf-8')

      console.log(`\n=== ${repo}/${path} ===\n${decoded}\n`)
      return decoded
    } else {
      console.error(`[gh-limine] Failed to read ${path}: ${response.status}`)
      return ''
    }
  } catch (error) {
    console.error(`[gh-limine] Error reading ${path}:`, error)
    return ''
  }
}

/**
 * List all limine-related repos we own or follow
 */
async function listLimineRepos() {
  const bunPath = await ensureBunVenv()

  const apiURL = 'https://api.github.com/search/repositories'
  const params = new URLSearchParams({
    q: 'Limine',
    sort: 'updated',
    order: 'desc',
    per_page: 100
  })

  const headers: Record<string, string> = {
    'Accept': 'application/vnd.github.v3+json'
  }

  const token = process.env.GITHUB_TOKEN || ''
  if (token) {
    headers['Authorization'] = `token ${token}`
  }

  try {
    const response = await fetch(`${apiURL}?${params}`, { headers })

    if (response.ok) {
      const data = await response.json()
      const repos = data.items || []

      console.log(`\n[gh-limine] Limine-related repos:\n`)

      for (const repo of repos) {
        const name = repo.full_name || ''
        const description = repo.description || ''
        const private = repo.private ? 'private' : 'public'
        const created = repo.created_at || ''

        console.log(`${name}\t${description}\t${private}\t${created}`)
      }

      return repos
    }
  } catch (error) {
    console.error(`[gh-limine] Failed to list repos:`, error)
  }
}

/**
 * Check if a limine repo exists
 */
async function checkLimineRepo(repo: string = LIMINE_REPOS.bootloader) {
  const bunPath = await ensureBunVenv()

  const apiURL = `https://api.github.com/repos/${repo}`
  const headers: Record<string, string> = {
    'Accept': 'application/vnd.github.v3+json'
  }

  const token = process.env.GITHUB_TOKEN || ''
  if (token) {
    headers['Authorization'] = `token ${token}`
  }

  try {
    const response = await fetch(apiURL, { headers })

    if (response.ok) {
      const data = await response.json()
      console.log(`✓ ${repo} exists (public)`)  
      return true
    } else if (response.status === 404) {
      console.log(`✗ ${repo} not found`)
      return false
    } else {
      console.error(`[gh-limine] Error checking repo: ${response.status}`)
      return false
    }
  } catch (error) {
    console.error(`[gh-limine] Failed to check repo:`, error)
    return false
  }
}

/**
 * Search for limine profile management patterns
 */
async function searchLimineProfile(query: string = 'profile') {
  return searchLimine(query, 50)
}

/**
 * Clone a limine repo
 */
async function cloneLimine(repo: string = LIMINE_REPOS.ctemplate, path: string = '.', depth: number = 2) {
  const bunPath = await ensureBunVenv()

  // Use git with shallow clone for speed
  await $`git clone --depth ${depth} https://github.com/${repo}.git ${path}`

  console.log(`[gh-limine] Cloned ${repo} to ${path}`)
}

/**
 * Get limine repo file content
 */
async function getLimineFile(repo: string = LIMINE_REPOS.bootloader, path: string = 'README.md', ref: string = 'main') {
  return viewLimineReadme(repo, path)
}

/**
 * Search for limine profile patterns in code
 */
async function searchLimineCode(query: string = 'profile') {
  const apiURL = 'https://api.github.com/search/code'
  const params = new URLSearchParams({
    q: `limine ${query}`,
    sort: 'indexed',
    order: 'desc',
    per_page: 50
  })

  const headers: Record<string, string> = {
    'Accept': 'application/vnd.github.cloak.v3+json'
  }

  const token = process.env.GITHUB_TOKEN || ''
  if (token) {
    headers['Authorization'] = `token ${token}`
  }

  try {
    const response = await fetch(`${apiURL}?${params}`, { headers })

    if (response.ok) {
      const data = await response.json()
      const files = data.items || []

      console.log(`\n[gh-limine] Found ${files.length} code matches for "${query}"\n`)

      for (const file of files.slice(0, 20)) {
        const path = file.path || ''
        const repository = file.repository?.full_name || ''
        const language = file.language || ''

        console.log(`${repository}/${path}\t${language}`)
      }

      return files
    }
  } catch (error) {
    console.error(`[gh-limine] Code search failed:`, error)
  }
}

// ============================================================================
// Main command dispatcher
// ============================================================================

async function main() {
  const command = process.argv[2] || 'help'
  const args = process.argv.slice(3)

  switch (command) {
    case 'search':
      const query = args[0] || 'limine'
      const limit = parseInt(args[1] || '50', 10)
      await searchLimine(query, limit)
      break

    case 'view':
      const repo = args[0] || LIMINE_REPOS.bootloader
      const file = args[1] || 'README.md'
      await viewLimineReadme(repo, file)
      break

    case 'list':
      await listLimineRepos()
      break

    case 'check':
      const checkRepo = args[0] || LIMINE_REPOS.bootloader
      await checkLimineRepo(checkRepo)
      break

    case 'profile':
      const profileQuery = args[0] || 'profile'
      await searchLimineProfile(profileQuery)
      break

    case 'code':
      const codeQuery = args[0] || 'profile'
      await searchLimineCode(codeQuery)
      break

    case 'clone':
      const cloneRepo = args[0] || LIMINE_REPOS.ctemplate
      const clonePath = args[1] || '.'
      const cloneDepth = parseInt(args[2] || '2', 10)
      await cloneLimine(cloneRepo, clonePath, cloneDepth)
      break

    case 'help':
    default:
      console.log(`gh-limine.ts - Bun-based GitHub control for limine kernel profiles\n`)
      console.log('Usage: bun gh-limine.ts <command> [args...]\n')
      console.log('Commands:')
      console.log('  search [query] [limit]    Search for limine repos')
      console.log('  view [repo] [path]       View a limine repo\'s README')
      console.log('  list                      List limine-related repos')
      console.log('  check [repo]             Check if a limine repo exists')
      console.log('  profile [query]          Search for limine profile patterns')
      console.log('  code [query]             Search for limine profile patterns in code')
      console.log('  clone [repo] [path] [depth] Clone a limine repo')
      console.log('  help                     Show this help message')
      console.log('')
      console.log('Environment:')
      console.log('  GITHUB_TOKEN    GitHub personal access token (optional)')
  }
}

